<script setup lang="ts">import {ref,watch} from 'vue';import {request} from '@/lib/request';const props=defineProps<{code:string}>(),model=defineModel<string>(),values=ref<{value:string;label:string}[]>([]),error=ref('');watch(()=>props.code,async()=>{try{values.value=await request('/api/platform/dictionary/'+encodeURIComponent(props.code));error.value=''}catch(e){values.value=[];error.value=e instanceof Error?e.message:'字典加载失败'}},{immediate:true})</script><template><el-select v-model="model" :placeholder="error||'请选择'"><el-option v-for="v in values" :key="v.value" :label="v.label" :value="v.value"/></el-select></template>